window.FBA=(function(){var D={"p1": "data:audio/mpeg;base64,", "p2": "data:audio/mpeg;base64,", "p3": "data:audio/mpeg;base64,", "r1": "data:audio/mpeg;base64,", "r2": "data:audio/mpeg;base64,", "r3": "data:audio/mpeg;base64,", "r4": "data:audio/mpeg;base64,"};
var P=['p1','p2','p3'],R=['r1','r2','r3','r4'],last=0,cur=null,lp=-1,lr=-1;
function pick(a,l){var i;do{i=Math.floor(Math.random()*a.length)}while(i===l&&a.length>1);return i}
function say(ok){var n=Date.now();if(n-last<700)return;last=n;try{if(cur){cur.pause()}var k;if(ok){lp=pick(P,lp);k=P[lp]}else{lr=pick(R,lr);k=R[lr]}cur=new Audio(D[k]);var p=cur.play();if(p&&p.catch)p.catch(function(){})}catch(e){}}
function sib(el){var p=el.parentNode;return p&&p.querySelector('.opt.no')}
try{new MutationObserver(function(ms){ms.forEach(function(m){var t=m.target,c=t.classList;if(!c)return;
if(c.contains('fb')){if(c.contains('ok'))say(true);else if(c.contains('no'))say(false)}
else if(c.contains('opt')){if(c.contains('no'))say(false);else if(c.contains('ok')&&!sib(t))say(true)}})}).observe(document.documentElement,{attributes:true,attributeFilter:['class'],subtree:true})}catch(e){}
return {say:say}})();
